from pathlib import Path
import os,subprocess,json,shutil
root=Path('/srv/projects/fadego')
base=root/'releases'
current=root/'current'
def run(args,t=15):
 return subprocess.run(args,capture_output=True,text=True,timeout=t)
def active(name):
 return run(['systemctl','is-active',name+'.service'],8).stdout.strip()
def bots():
 r=run(['pm2','jlist'],15)
 if r.returncode:raise RuntimeError('PM2 offline')
 return {a.get('name'):{'status':(a.get('pm2_env') or {}).get('status'),'pid':a.get('pid')} for a in json.loads(r.stdout) if a.get('name') in ('iptvpn_bot','telegram-robot-leads')}
services=['fadego-staging','pink-iptv-backend','pink-vpn','lowcost-europa','pm2-root','nginx','postgresql@16-main']
before={n:active(n) for n in services}
if any(x!='active' for x in before.values()):raise RuntimeError('Service baseline not active')
pm=bots()
if any(pm.get(n,{}).get('status')!='online' for n in ('iptvpn_bot','telegram-robot-leads')):raise RuntimeError('Telegram bot baseline failed')
if not root.is_dir() or root.is_symlink() or not base.is_dir() or base.is_symlink() or not current.is_symlink():raise RuntimeError('FADEGO layout not verified')
current_release=current.resolve()
if current_release.parent!=base:raise RuntimeError('Current release outside project')
dirs=sorted([x for x in base.iterdir() if x.is_dir() and not x.is_symlink()],key=lambda x:x.stat().st_mtime,reverse=True)
if len(dirs)!=9 or len(set(x.name for x in dirs))!=9:raise RuntimeError('Release count unexpectedly changed: '+str(len(dirs)))
retain={current_release,dirs[0],dirs[1]}
if len(retain)<3: retain.add(dirs[2])
candidates=[x for x in dirs if x not in retain]
if len(candidates)!=6:raise RuntimeError('Unexpected candidate count '+str(len(candidates)))
for x in candidates:
 if len(x.name)!=40 or not all(ch in '0123456789abcdef' for ch in x.name):raise RuntimeError('Unexpected release name')
 if x.stat().st_dev!=base.stat().st_dev:raise RuntimeError('Unexpected mount')
 if x.stat().st_uid!=root.stat().st_uid:raise RuntimeError('Release owner differs')
 if (x/'node_modules').is_symlink():raise RuntimeError('Unexpected node_modules symlink')
 danger=[]
 for dp,children,files in os.walk(x):
  rel=Path(dp).relative_to(x)
  if len(rel.parts)>3:children.clear();continue
  children[:]=[d for d in children if d not in ('node_modules','.next','.git','dist','build')]
  for name in children+files:
   q=rel/name
   if name.startswith('.env') or name.endswith(('.session','.sqlite','.sqlite3','.db')) or name.lower() in ('uploads','user-uploads','database.sqlite','private','credentials','secrets','storage'):
    danger.append(str(q))
 if danger:raise RuntimeError('Potential mutable project data in old release '+x.name+': '+str(danger[:8]))
for proc in Path('/proc').iterdir():
 if not proc.name.isdigit():continue
 try:
  cwd=os.readlink(proc/'cwd')
  for q in candidates:
   if cwd==str(q) or cwd.startswith(str(q)+'/'):raise RuntimeError('Candidate in use by process '+proc.name)
 except OSError:pass
for x in [root/'current']:
 if not x.resolve() in retain:raise RuntimeError('Current does not point to retained release')
size_before=int(run(['du','-x','-s','-B1',str(base)],70).stdout.split()[0])
free_before=shutil.disk_usage('/').free
print('KEEP_RELEASES='+','.join(sorted(x.name for x in retain)))
print('REMOVE_RELEASES='+','.join(x.name for x in candidates))
print('BEFORE_RELEASES_BYTES='+str(size_before))
print('OLD_RELEASES_TO_REMOVE='+str(len(candidates)))
for x in candidates:
 shutil.rmtree(x)
 print('PRUNED_OLD_RELEASE='+x.name)
for x in retain:
 if not x.is_dir():raise RuntimeError('Protected release missing: '+x.name)
if current.resolve()!=current_release:raise RuntimeError('Active release changed')
size_after=int(run(['du','-x','-s','-B1',str(base)],70).stdout.split()[0])
gain=shutil.disk_usage('/').free-free_before
print('AFTER_RELEASES_BYTES='+str(size_after))
print('RELEASES_DIRECTORY_SIZE_REDUCTION='+str(size_before-size_after))
print('DISK_FREE_GAIN_BYTES='+str(gain))
for name,value in before.items():
 actual=active(name)
 if actual!=value:raise RuntimeError('Service state changed after cleanup: '+name)
if bots()!=pm:raise RuntimeError('Telegram bot changed')
print('ACTIVE_FADEGO_RELEASE='+current_release.name)
print('FADEGO_RELEASES_PRESERVED='+str(len(retain)))
print('FADEGO_HYGIENE=PASS')
PY
